  'n2-1318': { ja: 'この[寺|てら]は[国内|こくない][最古|さいこ]の[木造|もくぞう][建造物|けんぞうぶつ]だ。', zh: '這座寺廟是國內最古老的木造建築物。' },
  'n2-1319': { ja: '[設計図|せっけいず]には[隠|かく]し[部屋|へや]が[描|えが]かれていた。', zh: '設計圖上畫著密室。' },
