  'n2-1441': { ja: '[羊毛|ようもう]のセーターは[暖|あたた]かい。', zh: '羊毛毛衣很暖和。' },
  'n2-1442': { ja: '[合成繊維|ごうせいせんい]は[乾|かわ]きやすい。', zh: '合成纖維容易乾。' },
  'n2-1443': { ja: 'この[服|ふく]には[化学繊維|かがくせんい]が[使|つか]われている。', zh: '這件衣服使用了化學纖維。' },
  'n2-1444': { ja: '[皮革|ひかく][製品|せいひん]の[手入|てい]れをする。', zh: '保養皮革製品。' },
  'n2-1445': { ja: 'ゴムの[手袋|てぶくろ]をはめて[掃除|そうじ]した。', zh: '戴著橡膠手套打掃。' },
  'n2-1446': { ja: 'この[部品|ぶひん]は[樹脂|じゅし]でできている。', zh: '這個零件是樹脂做的。' },
  'n2-1447': { ja: '[海|うみ]のプラスチックごみが[問題|もんだい]になっている。', zh: '海洋塑膠垃圾成了問題。' },
  'n2-1448': { ja: '[引っ越|ひっこ]しの[段|だん]ボールが[部屋|へや]に[積|つ]まれている。', zh: '搬家用的紙箱堆在房間裡。' },
  'n2-1449': { ja: '[壁|かべ]に[白|しろ]い[塗料|とりょう]を[塗|ぬ]った。', zh: '在牆上塗了白色塗料。' },
  'n2-1450': { ja: '[天然|てんねん]の[染料|せんりょう]で[布|ぬの]を[染|そ]める。', zh: '用天然染料染布。' },
  'n2-1451': { ja: 'この[条件|じょうけん]に[当|あ]てはまる[人物|じんぶつ]は[三人|さんにん]しかいない。', zh: '符合這個條件的人物只有三個。' },
  'n2-1452': { ja: '[母|はは]に[言い付|いいつ]けられた[用事|ようじ]を[忘|わす]れていた。', zh: '我忘了媽媽吩咐的事。' },
  'n2-1453': { ja: 'このジュースは[水|みず]で[薄|うす]めて[飲|の]む。', zh: '這果汁要加水稀釋來喝。' },
  'n2-1454': { ja: '[彼|かれ]はその[噂|うわさ]をすぐに[打ち消|うちけ]した。', zh: '他立刻否認了那個傳聞。' },
  'n2-1455': { ja: 'カードを[裏返|うらがえ]すと、[数字|すうじ]が[書|か]いてあった。', zh: '把卡片翻過來，上面寫著數字。' },
  'n2-1456': { ja: '[雨|あめ]が[乾|かわ]いた[大地|だいち]を[潤|うるお]した。', zh: '雨水滋潤了乾涸的大地。' },
  'n2-1457': { ja: '[走|はし]ってやっと[前|まえ]の[人|ひと]に[追い付|おいつ]いた。', zh: '跑著終於追上了前面的人。' },
  'n2-1458': { ja: '[祖父|そふ]は[毎朝|まいあさ][仏壇|ぶつだん]を[拝|おが]んでいる。', zh: '祖父每天早上對著佛壇參拜。' },
  'n2-1459': { ja: '[薬|くすり]を[飲|の]んだら[頭痛|ずつう]が[治|おさ]まった。', zh: '吃了藥後頭痛就緩解了。' },
  'n2-1460': { ja: '[荷物|にもつ]が[全部|ぜんぶ][箱|ばこ]に[収|おさ]まった。', zh: '行李全都裝進箱子裡了。' },
  'n2-1461': { ja: '[被害|ひがい]は[町|まち][全体|ぜんたい]に[及|およ]んだ。', zh: '災害波及了整個城鎮。' },
  'n2-1462': { ja: '[後|のち]ほど[折り返|おりかえ]しお[電話|でんわ]します。', zh: '稍後再回電給您。' },
  'n2-1463': { ja: '[彼|かれ]の[説明|せつめい]は[具体|ぐたい][性|せい]を[欠|か]いている。', zh: '他的說明缺乏具體性。' },
  'n2-1464': { ja: '[悪|わる]いことが[重|かさ]なって、[気分|きぶん]が[沈|しず]んだ。', zh: '壞事接二連三，心情很低落。' },
  'n2-1465': { ja: '[祭|まつ]りで[若者|わかもの]たちが[神輿|しんよ]を[担|かつ]いでいた。', zh: '祭典上年輕人們扛著神轎。' },
  'n2-1466': { ja: 'イヤホンのコードが[絡|から]まってしまった。', zh: '耳機線纏在一起了。' },
  'n2-1467': { ja: '[文章|ぶんしょう]を[段落|だんらく]で[区切|くぎ]ると[読|よ]みやすくなる。', zh: '把文章分段會比較好讀。' },
  'n2-1468': { ja: '[落|お]としたグラスが[粉々|こなごな]に[砕|くだ]けた。', zh: '掉落的玻璃杯摔得粉碎。' },
  'n2-1469': { ja: '[坂|さか]を[下|くだ]ると[古|ふる]い[神社|じんじゃ]がある。', zh: '下坡後有一座古老的神社。' },
  'n2-1470': { ja: '[雨|あめ]のせいで[予定|よてい]が[狂|くる]った。', zh: '因為下雨，預定全打亂了。' },
  'n2-1471': { ja: '[彼|かれ]は[客|きゃく]の[扱|あつか]い[方|かた]をよく[心得|こころえ]ている。', zh: '他很懂得如何應對客人。' },
  'n2-1472': { ja: '[彼女|かのじょ]は[医者|いしゃ]を[志|こころざ]して[勉強|べんきょう]している。', zh: '她立志當醫生而努力讀書。' },
  'n2-1473': { ja: '[母|はは]が[弁当|べんとう]を[拵|こしら]えてくれた。', zh: '媽媽幫我做了便當。' },
  'n2-1474': { ja: '[眠|ねむ]そうに[目|め]を[擦|こす]っている。', zh: '他睏得直揉眼睛。' },
  'n2-1475': { ja: '[証人|しょうにん]によって[話|はなし]の[内容|ないよう]が[異|こと]なる。', zh: '證人說的內容各不相同。' },
  'n2-1476': { ja: '[布|ぬの]を[細|ほそ]く[裂|さ]いて[包帯|ほうたい]の[代|か]わりにした。', zh: '把布撕成細條當作繃帶。' },
  'n2-1477': { ja: '[彼|かれ]は[一生|いっしょう]を[研究|けんきゅう]に[捧|ささ]げた。', zh: '他將一生奉獻給研究。' },
  'n2-1478': { ja: '[指|ゆび]にとげが[刺|さ]さって[痛|いた]い。', zh: '手指扎到刺，好痛。' },
  'n2-1479': { ja: '[週末|しゅうまつ]までにレポートを[仕上|しあ]げなければならない。', zh: '週末前必須完成報告。' },
  'n2-1480': { ja: 'このふたはしっかり[締|し]まらない。', zh: '這個蓋子關不緊。' },
  'n2-1481': { ja: '[山|やま]の[空気|くうき]は[澄|す]んでいて[気持|きも]ちがいい。', zh: '山上的空氣清新，很舒服。' },
  'n2-1482': { ja: '[夕日|ゆうひ]で[空|そら]が[赤|あか]く[染|そ]まった。', zh: '天空被夕陽染紅了。' },
  'n2-1483': { ja: '[質問|しつもん]されると、[彼|かれ]は[目|め]を[逸|そ]らした。', zh: '被問到時，他把視線移開了。' },
  'n2-1484': { ja: '[祖父|そふ]は[毎朝|まいあさ][畑|はたけ]を[耕|たがや]している。', zh: '祖父每天早上耕田。' },
