  'n2-1486': { ja: '[最近|さいきん]、[気持|きも]ちが[弛|たる]んでいるぞ。', zh: '最近你精神很鬆懈喔。' },
  'n2-1487': { ja: '[風|かぜ]が[桜|さくら]の[花|はな]びらを[散|ち]らした。', zh: '風吹落了櫻花花瓣。' },
  'n2-1488': { ja: '[車|くるま]が[店|みせ]に[突っ込|つっこ]む[事故|じこ]があった。', zh: '發生了車子衝進店裡的事故。' },
  'n2-1489': { ja: '[毎日|まいにち][早|はや]く[寝|ね]るように[努|つと]めている。', zh: '我每天努力早點睡。' },
  'n2-1490': { ja: '[子|こ]どもたちが[野原|のはら]で[花|はな]を[摘|つ]んでいる。', zh: '孩子們在原野上摘花。' },
  'n2-1491': { ja: '[透き通|すきとお]った[海|うみ]で[泳|およ]いだ。', zh: '在清澈透明的海裡游泳。' },
  'n2-1492': { ja: '[料理|りょうり]の[前|まえ]に[包丁|ほうちょう]を[研|みが]いだ。', zh: '做菜前先磨了菜刀。' },
  'n2-1493': { ja: '[資料|しりょう]をホチキスで[綴|と]じておいた。', zh: '用釘書機把資料裝訂好了。' },
