  'n2-1496': { ja: '[途中|とちゅう]で[仕事|しごと]を[投げ出|なげだ]すのはよくない。', zh: '做到一半就放棄工作不好。' },
  'n2-1497': { ja: '[誰|だれ]かが[玄関|げんかん]のベルを[鳴|な]らした。', zh: '有人按了玄關的門鈴。' },
  'n2-1498': { ja: '[少|すこ]しずつ[体|からだ]を[寒|さむ]さに[慣|な]らしていく。', zh: '讓身體一點一點適應寒冷。' },
  'n2-1499': { ja: '[転校生|てんこうせい]はすぐにクラスに[馴染|なじ]んだ。', zh: '轉學生很快就融入了班級。' },
