  'n2-1501': { ja: '[野菜|やさい]がよく[煮|に]えたら[火|ひ]を[止|と]める。', zh: '蔬菜煮透後就關火。' },
  'n2-1502': { ja: '[彼|かれ]は[会議|かいぎ]をこっそり[抜け出|ぬけだ]した。', zh: '他偷偷溜出了會議。' },
  'n2-1503': { ja: '[壁|かべ]のペンキが[剥|は]げている。', zh: '牆上的油漆剝落了。' },
