  'n2-1505': { ja: '[帰|かえ]ろうとする[客|きゃく]を[引き止|ひきと]めた。', zh: '挽留了要回去的客人。' },
  'n2-1506': { ja: 'タオルを[水|みず]に[浸|ひた]して[額|がく]に[当|あ]てた。', zh: '把毛巾浸水後敷在額頭上。' },
  'n2-1507': { ja: '[話し合|はなしあ]いを[通|とお]して[理解|りかい]を[深|ふか]めた。', zh: '透過討論加深了理解。' },
