  'n2-1510': { ja: '[二|に][本|ほん]の[道|みち]が[交|まじ]わる[所|ところ]に[交番|こうばん]がある。', zh: '兩條路交會處有派出所。' },
  'n2-1511': { ja: '[旅人|たびびと]にわずかなお[金|かね]を[恵|めぐ]んだ。', zh: '施捨了少許錢給旅人。' },
  'n2-1512': { ja: '[多|おお]くの[人|ひと]が[彼|かれ]に[期待|きたい]を[寄|よ]せている。', zh: '許多人對他寄予期望。' },
