  'n2-1514': { ja: 'この[本|ほん]は[日本語|にほんご]の[起源|きげん]を[論|ろん]じている。', zh: '這本書論述日語的起源。' },
  'n2-1515': { ja: '[列|れつ]に[割り込|わりこ]むのはマナー[違反|いはん]だ。', zh: '插隊是違反禮儀的。' },
  'n2-1516': { ja: '[小説|しょうせつ]の[結末|けつまつ]を[書き換|かきか]えることにした。', zh: '決定改寫小說的結局。' },
  'n2-1517': { ja: '[帰|かえ]りに[本屋|ほんや]に[立ち寄|たちよ]った。', zh: '回家途中順道去了書店。' },
  'n2-1518': { ja: '[批判|ひはん]を[真剣|しんけん]に[受け止|うけと]める。', zh: '認真看待批評。' },
  'n2-1519': { ja: '[明日|あした]の[発表|はっぴょう]について[先生|せんせい]と[打ち合|うちあ]わせた。', zh: '和老師討論了明天的發表。' },
  'n2-1520': { ja: '[面倒|めんどう]な[仕事|しごと]を[後輩|こうはい]に[押し付|おしつ]けるな。', zh: '別把麻煩工作推給後輩。' },
  'n2-1521': { ja: '[開店|かいてん]と[同時|どうじ]に[客|きゃく]が[押し寄|おしよ]せた。', zh: '一開店客人就蜂擁而至。' },
  'n2-1522': { ja: '[知|し]らせを[聞|き]いて[病院|びょういん]に[駆け付|かけつ]けた。', zh: '聽到消息後急忙趕到醫院。' },
  'n2-1523': { ja: '[気持|きも]ちを[切り替|きりか]えて[次|つぎ]の[試合|しあい]に[臨|のぞ]む。', zh: '轉換心情迎接下一場比賽。' },
  'n2-1524': { ja: '[応募|おうぼ]は[昨日|きのう]で[締め切|しめき]られた。', zh: '報名在昨天截止了。' },
  'n2-1525': { ja: 'この[道|みち]を[突き当|つきあ]たったら[右|みぎ]に[曲|ま]がってください。', zh: '這條路走到底後請右轉。' },
  'n2-1526': { ja: '[探偵|たんてい]は[密室|みっしつ]の[謎|なぞ]を[解き明|ときあ]かした。', zh: '偵探解開了密室之謎。' },
  'n2-1527': { ja: '[記者|きしゃ]は[取材|しゅざい]で[全国|ぜんこく]を[飛び回|とびまわ]っている。', zh: '記者為了採訪奔走全國。' },
  'n2-1528': { ja: 'この[店|みせ]では[外国|がいこく]の[本|ほん]も[取り扱|とりあつか]っている。', zh: '這家店也經銷外國書籍。' },
  'n2-1529': { ja: '[地方|ちほう]の[名産|めいさん]をネットで[取り寄|とりよ]せた。', zh: '在網路上訂購了地方名產。' },
  'n2-1530': { ja: '[電話|でんわ]の[男|おとこ]は[警察官|けいさつかん]だと[名乗|なの]った。', zh: '電話裡的男人自稱是警察。' },
  'n2-1531': { ja: '[二|ふた]つの[事件|じけん]は[手口|てぐち]がよく[似通|にかよ]っている。', zh: '兩起事件的手法非常相似。' },
  'n2-1532': { ja: '[文章|ぶんしょう]から[大事|だいじ]な[語|かたり]を[抜き出|ぬきだ]してください。', zh: '請從文章中挑出重要詞語。' },
  'n2-1533': { ja: '[会社|かいしゃ]は[来月|らいげつ]から[給料|きゅうりょう]を[引き上|ひきあ]げる。', zh: '公司從下個月起調高薪水。' },
  'n2-1534': { ja: '[銀行|ぎんこう]が[金利|きんり]を[引き下|ひきさ]げた。', zh: '銀行調降了利率。' },
