  'n2-1536': { ja: '[迷子|まいご]の[犬|いぬ]を[飼い主|かいぬし]が[引き取|ひきと]りに[来|き]た。', zh: '飼主來領回走失的狗。' },
  'n2-1537': { ja: '[台風|たいふう]のため[電車|でんしゃ]の[運転|うんてん]を[見合|みあ]わせている。', zh: '因為颱風電車暫停行駛。' },
  'n2-1538': { ja: '[財布|さいふ]がどこにも[見当|みあ]たらない。', zh: '錢包哪裡都找不到。' },
  'n2-1539': { ja: '[十|じゅう][年|ねん][先|さき]を[見通|みとお]して[計画|けいかく]を[立|た]てる。', zh: '預見十年後來擬定計畫。' },
  'n2-1540': { ja: '[飲み物|のみもの]を[館内|かんない]に[持ち込|もちこ]まないでください。', zh: '請勿將飲料帶入館內。' },
  'n2-1541': { ja: '[警官|けいかん]に[呼び止|よびと]められて[職務|しょくむ][質問|しつもん]を[受|う]けた。', zh: '被警察叫住接受盤查。' },
  'n2-1542': { ja: '[一人|ひとり][一人|ひとり]に[役割|やくわり]を[割り当|わりあ]てた。', zh: '給每個人分配了角色。' },
  'n2-1543': { ja: '[壁|かべ]に[小型|こがた]のカメラが[埋め込|うめこ]まれていた。', zh: '牆裡嵌了一台小型攝影機。' },
  'n2-1544': { ja: '[祖母|そぼ]はスマホを[使|つか]いこなしている。', zh: '祖母能熟練使用智慧型手機。' },
  'n2-1545': { ja: '[大丈夫|だいじょうぶ]だと[自分|じぶん]に[言い聞|いいき]かせた。', zh: '我對自己說沒問題的。' },
  'n2-1546': { ja: '[上司|じょうし]の[小言|こごと]は[聞き流|ききなが]すことにしている。', zh: '我把上司的嘮叨當耳邊風。' },
  'n2-1547': { ja: '[忘|わす]れないように[手帳|てちょう]に[書き留|かきと]めた。', zh: '為了不忘記，記在了手冊上。' },
  'n2-1548': { ja: '[留守|るす]のようなので、また[出直|でなお]します。', zh: '好像不在家，我改天再來。' },
