  'n2-1565': { ja: '[祖父|そふ]は[渋|しぶ]い[色|いろ]の[着物|きもの]が[好|す]きだ。', zh: '祖父喜歡素雅顏色的和服。' },
  'n2-1566': { ja: '[列|れつ]に[割り込|わりこ]むなんて[図々|ずうずう]しい[人|ひと]だ。', zh: '插隊真是厚臉皮的人。' },
  'n2-1567': { ja: '[刑事|けいじ]は[素早|すばや]く[犯人|はんにん]を[取り押|とりお]さえた。', zh: '刑警迅速制伏了犯人。' },
