  'n2-1575': { ja: '[書類|しょるい]を[書き直|かきなお]すのは[面倒臭|めんどうくさ]い。', zh: '重寫文件好麻煩。' },
  'n2-1576': { ja: '[夜中|やちゅう]に[物凄|ものすご]い[音|おと]がした。', zh: '半夜響起了驚人的聲音。' },
