  'n2-1585': { ja: '[台所|だいどころ]が[魚|さかな]で[生臭|なまぐさ]い。', zh: '廚房有魚腥味。' },
  'n2-1586': { ja: 'その[考え方|かんがえかた]はもう[古臭|ふるくさ]い。', zh: '那種想法已經過時了。' },
