  'n2-2089': { ja: '[通説|つうせつ]とは[異|こと]なる[結論|けつろん]が[出|で]た。', zh: '得出了與普遍說法不同的結論。' },
  'n2-2090': { ja: 'キャンプでは[炊事|すいじ]を[交代|こうたい]で[担当|たんとう]する。', zh: '露營時輪流負責煮飯。' },
  'n2-2091': { ja: '[家族|かぞく]そろって[食卓|しょくたく]を[囲|かこ]んだ。', zh: '全家人圍著餐桌坐。' },
  'n2-2092': { ja: '[冬|ふゆ][用|よう]の[寝具|しんぐ]を[押し入|おしい]れから[出|だ]した。', zh: '從壁櫥拿出了冬天用的寢具。' },
  'n2-2093': { ja: '[駅前|えきまえ]に[小|ちい]さな[雑貨|ざっか][屋|や]ができた。', zh: '車站前開了一家小雜貨店。' },
  'n2-2094': { ja: '[週末|しゅうまつ]に[日用品|にちようひん]をまとめて[買|か]う。', zh: '週末一次購買日用品。' },
  'n2-2095': { ja: '[最近|さいきん]は[服|ふく]も[通販|つうはん]で[買|か]うことが[多|おお]い。', zh: '最近連衣服也常網購。' },
  'n2-2096': { ja: '[隣|となり]の[家|いえ]に[回覧板|かいらんばん]を[回|まわ]した。', zh: '把社區傳閱板傳給隔壁鄰居。' },
  'n2-2097': { ja: '[旅行|りょこう]の[土産|みやげ]に[地元|じもと]のお[菓子|かし]を[買|か]った。', zh: '買了當地的點心作為旅行伴手禮。' },
  'n2-2098': { ja: '[秋|あき]は[行楽|こうらく]に[最適|さいてき]な[季節|きせつ]だ。', zh: '秋天是最適合出遊的季節。' },
  'n2-2099': { ja: '[午後|ごご]に[来客|らいきゃく]の[予定|よてい]がある。', zh: '下午預定有客人來訪。' },
  'n2-2100': { ja: '[突然|とつぜん]の[訪問|ほうもん]で[申し訳|もうしわけ]ありません。', zh: '很抱歉突然來拜訪。' },
  'n2-2101': { ja: 'お[世話|せわ]になった[人|ひと]にお[歳暮|せいぼ]を[贈|おく]る。', zh: '向照顧過自己的人送年終禮品。' },
  'n2-2102': { ja: '[取引|とりひき][先|さき]からお[中元|ちゅうげん]が[届|とど]いた。', zh: '客戶寄來了中元禮品。' },
  'n2-2103': { ja: '[冠婚葬祭|かんこんそうさい]のマナーを[学|まな]んでおく。', zh: '事先學好婚喪喜慶的禮儀。' },
  'n2-2104': { ja: '[祖父|そふ]の[葬式|そうしき]には[大勢|たいせい]の[人|ひと]が[来|き]た。', zh: '爺爺的葬禮來了很多人。' },
  'n2-2105': { ja: '[友人|ゆうじん]の[結婚|けっこん][披露宴|ひろうえん]でスピーチをした。', zh: '在朋友的結婚喜宴上致詞。' },
  'n2-2106': { ja: '[新|あたら]しい[命|いのち]の[誕生|たんじょう]を[家族|かぞく]で[喜|よろこ]んだ。', zh: '全家為新生命的誕生而欣喜。' },
  'n2-2107': { ja: '[父|ちち]の[還暦|かんれき]を[家族|かぞく]で[祝|いわ]った。', zh: '全家一起為爸爸慶祝六十大壽。' },
  'n2-2108': { ja: '[長寿|ちょうじゅ]の[秘訣|ひけつ]は[早寝|はやね][早起|はやお]きだそうだ。', zh: '據說長壽的祕訣是早睡早起。' },
  'n2-2109': { ja: '[彼|かれ]は[生涯|しょうがい]を[研究|けんきゅう]に[捧|ささ]げた。', zh: '他將一生奉獻給研究。' },
  'n2-2110': { ja: 'このご[恩|おん]は[一生|いっしょう][忘|わす]れません。', zh: '這份恩情我一輩子都不會忘記。' },
  'n2-2111': { ja: 'あの[日|ひ]の[出会|であ]いは[運命|うんめい]だったと[思|おも]う。', zh: '我覺得那天的相遇是命運。' },
  'n2-2112': { ja: '[本人|ほんにん]の[意思|いし]を[確認|かくにん]してから[決|き]めよう。', zh: '確認本人的意向後再決定吧。' },
  'n2-2113': { ja: '[彼|かれ]は[医者|いしゃ]になるという[志|こころざし]を[持|も]っている。', zh: '他懷抱著成為醫生的志向。' },
  'n2-2114': { ja: '[新|あたら]しい[支払|しはら]い[方式|ほうしき]が[導入|どうにゅう]された。', zh: '導入了新的付款方式。' },
  'n2-2115': { ja: '[事故|じこ]を[防|ふせ]ぐ[方策|ほうさく]を[考|かんが]える[必要|ひつよう]がある。', zh: '必須想出防止事故的辦法。' },
  'n2-2116': { ja: '[科学|かがく][技術|ぎじゅつ]の[進歩|しんぽ]は[目覚|めざ]ましい。', zh: '科學技術的進步令人驚嘆。' },
  'n2-2117': { ja: '[為替|かわせ]の[変動|へんどう]が[激|はげ]しい。', zh: '匯率波動劇烈。' },
  'n2-2118': { ja: '[気分|きぶん][転換|てんかん]に[少|すこ]し[散歩|さんぽ]しよう。', zh: '出去散散步轉換一下心情吧。' },
  'n2-2119': { ja: '[二人|ふたり]の[証言|しょうげん]は[完全|かんぜん]に[一致|いっち]した。', zh: '兩人的證詞完全一致。' },
  'n2-2120': { ja: '[両者|りょうしゃ]の[考え方|かんがえかた]には[大|おお]きな[差異|さい]がある。', zh: '兩者的想法有很大的差異。' },
  'n2-2121': { ja: '[双子|ふたご]なので[区別|くべつ]がつかない。', zh: '因為是雙胞胎所以分辨不出來。' },
  'n2-2122': { ja: '[二|ふた]つの[事件|じけん]には[共通点|きょうつうてん]がある。', zh: '兩起案件有共同點。' },
  'n2-2123': { ja: '[光|ひかり]と[影|かげ]の[対比|たいひ]が[美|うつく]しい[写真|しゃしん]だ。', zh: '這是一張光影對比很美的照片。' },
  'n2-2124': { ja: '[例|たと]えを[使|つか]って[説明|せつめい]するとわかりやすい。', zh: '用比方來說明會比較容易懂。' },
  'n2-2125': { ja: '[実例|じつれい]を[挙|あ]げて[説明|せつめい]してください。', zh: '請舉實際例子說明。' },
  'n2-2126': { ja: '[過去|かこ]の[事例|じれい]を[参考|さんこう]に[対策|たいさく]を[立|た]てる。', zh: '參考過去的案例擬定對策。' },
  'n2-2127': { ja: '[先生|せんせい]の[字|じ]を[手本|てほん]にして[練習|れんしゅう]した。', zh: '以老師的字為範本練習。' },
  'n2-2128': { ja: '[基礎|きそ]ができれば[応用|おうよう]は[簡単|かんたん]だ。', zh: '打好基礎後應用就很簡單。' },
  'n2-2129': { ja: '[議論|ぎろん]の[焦点|しょうてん]がずれてしまった。', zh: '討論的焦點偏移了。' },
  'n2-2130': { ja: '[警察|けいさつ]は[現場|げんば][周辺|しゅうへん]を[詳|くわ]しく[調|しら]べた。', zh: '警方詳細調查了現場周邊。' },
  'n2-2131': { ja: 'この[部分|ぶぶん]だけもう[一度|いちど][説明|せつめい]してください。', zh: '請再說明一次這個部分。' },
  'n2-2132': { ja: '[書類|しょるい]の[一部|いちぶ]が[消|き]えていた。', zh: '文件的一部分不見了。' },
  'n2-2133': { ja: '[仕事|しごと]の[大部分|だいぶぶん]は[午前|ごぜん][中|ちゅう]に[終|お]わった。', zh: '大部分的工作在上午就完成了。' },
  'n2-2134': { ja: '[彼|かれ]は[日本|にほん][文化|ぶんか][全般|ぜんぱん]に[詳|くわ]しい。', zh: '他對日本文化整體都很熟悉。' },
