  'n2-2136': { ja: '[子|こ]どもたちは[集団|しゅうだん]で[登校|とうこう]する。', zh: '孩子們集體上學。' },
  'n2-2137': { ja: '[村|むら]は[一|ひと]つの[共同体|きょうどうたい]として[助け合|たすけあ]ってきた。', zh: '村子作為一個共同體互相扶持至今。' },
