  'n2-2139': { ja: '[相手|あいて]の[意見|いけん]を[尊重|そんちょう]しよう。', zh: '尊重對方的意見吧。' },
  'n2-2140': { ja: 'その[事件|じけん]はいつしか[忘却|ぼうきゃく]のかなたに[消|き]えた。', zh: '那起事件不知不覺消失在遺忘的彼方。' },
  'n2-2141': { ja: 'このカフェは[落ち着|おちつ]いた[雰囲気|ふんいき]がある。', zh: '這家咖啡店氣氛很沉穩。' },
  'n2-2142': { ja: '[彼|かれ]の[不自然|ふしぜん]な[振る舞|ふるま]いが[気|き]になった。', zh: '他不自然的舉止令人在意。' },
