  'n2-2146': { ja: '[親子|おやこ]の[対話|たいわ]を[大切|たいせつ]にしている。', zh: '重視親子之間的對話。' },
  'n2-2147': { ja: 'その[説明|せつめい]では[納得|なっとく]がいかない。', zh: '那種說明無法讓人信服。' },
