  'n2-2151': { ja: '[着物|きもの]の[帯|おび]を[一人|ひとり]で[結|むす]ぶのは[難|むずか]しい。', zh: '一個人綁和服腰帶很難。' },
  'n2-2152': { ja: '[暑|あつ]いので[扇子|せんす]であおいだ。', zh: '因為很熱，用摺扇搧風。' },
