  'n2-2154': { ja: '[祭|まつ]りの[太鼓|たいこ]の[音|おと]が[遠|とお]くから[聞|き]こえる。', zh: '遠處傳來祭典的太鼓聲。' },
  'n2-2155': { ja: '[彼女|かのじょ]は[三味線|しゃみせん]の[名手|めいしゅ]だ。', zh: '她是三味線高手。' },
  'n2-2156': { ja: 'お[正月|しょうがつ]に[琴|こと]の[演奏|えんそう]を[聞|き]いた。', zh: '過年時聽了日本箏的演奏。' },
