  'n2-2162': { ja: '[十|じゅう][年|ねん]ぶりの[帰郷|ききょう]で[町|まち]の[変化|へんか]に[驚|おどろ]いた。', zh: '睽違十年返鄉，對城鎮的變化感到吃驚。' },
