  'n2-2164': { ja: 'りんごはこの[地方|ちほう]の[特産|とくさん]だ。', zh: '蘋果是這個地方的特產。' },
  'n2-2165': { ja: 'すし[職人|しょくにん]になるには[長|なが]い[修業|しゅうぎょう]が[必要|ひつよう]だ。', zh: '要成為壽司師傅需要長時間修業。' },
  'n2-2166': { ja: 'この[絵|え]には[独特|どくとく]の[技法|ぎほう]が[使|つか]われている。', zh: '這幅畫使用了獨特的技法。' },
