  'n2-2168': { ja: '[学芸|がくげい][会|かい]で[主役|しゅやく]に[選|えら]ばれた。', zh: '在學藝會上被選為主角。' },
  'n2-2169': { ja: 'この[映画|えいが]は[筋|すじ]が[複雑|ふくざつ]でわかりにくい。', zh: '這部電影情節複雜難懂。' },
  'n2-2170': { ja: '[会社|かいしゃ]の[説明会|せつめいかい]に[参加|さんか]した。', zh: '參加了公司的說明會。' },
  'n2-2171': { ja: 'この[授業|じゅぎょう]は[必修|ひっしゅう]なので[休|やす]めない。', zh: '這門課是必修，所以不能缺席。' },
  'n2-2172': { ja: '[夏休|なつやす]みに[数学|すうがく]の[補習|ほしゅう]を[受|う]けた。', zh: '暑假上了數學補課。' },
  'n2-2173': { ja: '[風邪|かぜ]で[休|やす]んだので[追試|ついし]を[受|う]けた。', zh: '因感冒請假，所以參加了補考。' },
  'n2-2174': { ja: 'オンラインで[講座|こうざ]を[受講|じゅこう]している。', zh: '正在線上修習講座。' },
  'n2-2175': { ja: 'この[学校|がっこう]は[校則|こうそく]が[厳|きび]しい。', zh: '這所學校校規很嚴格。' },
  'n2-2176': { ja: '[小学校|しょうがっこう]の[給食|きゅうしょく]が[懐|なつ]かしい。', zh: '很懷念小學的營養午餐。' },
  'n2-2177': { ja: '[毎朝|まいあさ][八時|はちじ]までに[登校|とうこう]する。', zh: '每天早上八點前到校。' },
  'n2-2178': { ja: '[下校|げこう]の[時間|じかん]に[雨|あめ]が[降り出|ふりだ]した。', zh: '放學時開始下雨了。' },
  'n2-2179': { ja: '[不登校|ふとうこう]の[子|こ]どもを[支|ささ]える[活動|かつどう]がある。', zh: '有支援拒學孩童的活動。' },
  'n2-2180': { ja: '[学級|がっきゅう]で[話し合|はなしあ]ってルールを[決|き]めた。', zh: '全班討論決定了規則。' },
  'n2-2181': { ja: '[彼女|かのじょ]は[生徒会|せいとかい]の[会長|かいちょう]を[務|つと]めている。', zh: '她擔任學生會會長。' },
  'n2-2182': { ja: '[修学旅行|しゅうがくりょこう]で[京都|きょうと]と[奈良|なら]に[行|い]った。', zh: '畢業旅行去了京都和奈良。' },
  'n2-2183': { ja: '[彼|かれ]は[海外|かいがい]の[大学|だいがく]で[学位|がくい]を[取|と]った。', zh: '他在國外大學取得了學位。' },
  'n2-2184': { ja: '[教授|きょうじゅ]は[研究室|けんきゅうしつ]で[倒|たお]れているのを[発見|はっけん]された。', zh: '教授被發現倒在研究室裡。' },
  'n2-2185': { ja: '[詩|し]の[朗読|ろうどく][会|かい]に[参加|さんか]した。', zh: '參加了詩歌朗讀會。' },
  'n2-2186': { ja: '[小|ちい]さな[異変|いへん]も[見過|みす]ごしてはいけない。', zh: '即使是小小的異狀也不能放過。' },
  'n2-2187': { ja: '[困|こま]っている[仲間|なかま]を[見捨|みす]てることはできない。', zh: '不能對有困難的夥伴棄之不顧。' },
  'n2-2188': { ja: '[人込|ひとご]みの[中|なか]で[容疑|ようぎ][者|しゃ]を[見失|みうしな]った。', zh: '在人群中跟丟了嫌犯。' },
  'n2-2189': { ja: '[彼|かれ]の[表情|ひょうじょう]から[何|なに]も[読み取|よみと]れなかった。', zh: '從他的表情中看不出任何東西。' },
