  'n2-2296': { ja: '[市民|しみん][会館|かいかん]で[講演会|こうえんかい]が[開|ひら]かれた。', zh: '市民會館舉辦了演講會。' },
  'n2-2297': { ja: '[海外|かいがい]から[研修生|けんしゅうせい]を[受け入|うけい]れている。', zh: '接收來自海外的受訓學員。' },
  'n2-2298': { ja: '[彼女|かのじょ]は[大学|だいがく]で[教職|きょうしょく]の[資格|しかく]を[取|と]った。', zh: '她在大學取得了教師資格。' },
  'n2-2299': { ja: '[選択科目|せんたくかもく]で[心理|しんり][学|がく]を[取|と]った。', zh: '選修了心理學。' },
