  'n2-2301': { ja: '[大学|だいがく]の[授業|じゅぎょう]を[聴講|ちょうこう]させてもらった。', zh: '獲准旁聽大學的課程。' },
  'n2-2302': { ja: '[図書館|としょかん]に[入|はい]るには[学生証|がくせいしょう]が[必要|ひつよう]だ。', zh: '進圖書館需要學生證。' },
  'n2-2303': { ja: '[学校|がっこう]での[体罰|たいばつ]は[禁止|きんし]されている。', zh: '學校禁止體罰。' },
  'n2-2304': { ja: '[始業式|しぎょうしき]で[校長|こうちょう][先生|せんせい]の[話|はなし]を[聞|き]いた。', zh: '在開學典禮上聽了校長講話。' },
  'n2-2305': { ja: '[終業式|しゅうぎょうしき]が[終|お]わると[夏休|なつやす]みが[始|はじ]まる。', zh: '結業式結束後暑假就開始了。' },
  'n2-2306': { ja: '[彼|かれ]は[心理|しんり][学|がく]の[修士|しゅうし][課程|かてい]に[在籍|ざいせき]している。', zh: '他就讀心理學碩士班。' },
  'n2-2307': { ja: '[速読|そくどく]を[身|み]につければ[多|おお]くの[本|ほん]が[読|よ]める。', zh: '學會速讀就能讀很多書。' },
  'n2-2308': { ja: '[大事|だいじ]な[論文|ろんぶん]は[精読|せいどく]する[必要|ひつよう]がある。', zh: '重要的論文必須精讀。' },
  'n2-2309': { ja: '[多読|たどく]で[自然|しぜん]に[語彙|ごい]が[増|ふ]えた。', zh: '透過大量閱讀，詞彙自然增加了。' },
  'n2-2310': { ja: '[毎朝|まいあさ][教科書|きょうかしょ]を[音読|おんどく]している。', zh: '每天早上大聲朗讀課本。' },
