  'n2-2342': { ja: '[衣食住|いしょくじゅう]に[困|こま]らない[生活|せいかつ]を[送|おく]りたい。', zh: '想過著食衣住無虞的生活。' },
  'n2-2343': { ja: '[大学|だいがく][時代|じだい]は[古|ふる]い[下宿|げしゅく]に[住|す]んでいた。', zh: '大學時期住在老舊的寄宿房。' },
  'n2-2344': { ja: '[身の回|みのまわ]りの[物|もの]を[整理|せいり]した。', zh: '整理了身邊的東西。' },
