  'n2-2354': { ja: '[週末|しゅうまつ]に[部屋|へや]の[模様替|もようが]えをした。', zh: '週末重新布置了房間。' },
  'n2-2355': { ja: '[久|ひさ]しぶりに[母|はは]の[手料理|てりょうり]を[食|た]べた。', zh: '睽違許久吃到了媽媽親手做的菜。' },
  'n2-2356': { ja: '[昨日|きのう]の[残り物|のこりもの]で[昼|ひる]ご[飯|はん]を[作|つく]った。', zh: '用昨天的剩菜做了午餐。' },
